
// laboratoryQuestions.js

// =====================================================
// GERADORES DE QUESTÕES
// =====================================================

export function buildQuestions(section, week, day, rows = []) {

  return rows.map(
    ([prompt, options, correctAnswer, explanation], index) => ({

      id: `${section}-w${week}-d${day}-q${index + 1}`,

      prompt,
      options,
      correctAnswer,
      explanation

    })
  );

}


export function buildRecovery(section, week, rows = []) {

  return rows.map(
    ([prompt, options, correctAnswer, explanation], index) => ({

      id: `${section}-w${week}-recovery-q${index + 1}`,

      prompt,
      options,
      correctAnswer,
      explanation

    })
  );

}


